package com.company.logicdelete.runtime;
import com.fasterxml.jackson.databind.ObjectMapper;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.util.Map;
public class FileRuntimeSqlEventReporter implements RuntimeSqlEventReporter {private final Path path;private final ObjectMapper mapper=new ObjectMapper();public FileRuntimeSqlEventReporter(String path){this.path=Paths.get(path);}public synchronized void report(Map<String,Object>e){try{Path parent=path.toAbsolutePath().getParent();if(parent!=null)Files.createDirectories(parent);Files.write(path,(mapper.writeValueAsString(e)+System.lineSeparator()).getBytes(StandardCharsets.UTF_8),StandardOpenOption.CREATE,StandardOpenOption.APPEND);}catch(Exception ignored){/* tracing must never break business execution */}}}
